"use client"

import * as React from "react"

// The chart's shared state: its config, its id (which scopes the mark patterns) and the defaults that give every
// series a mark. One pen draws the whole chart, so series differ by mark (solid, outline, dotted, lined), not colour.

// Format: { THEME_NAME: CSS_SELECTOR }. Fineliner's night paper is data-theme="night" on the root, not shadcn's .dark.
export const THEMES = { light: "", dark: ':root[data-theme="night"]' } as const

/**
 * How a series fills its bars, areas and slices and marks its points: solid ink, an outline on bare paper, a
 * stipple of pen dots, or pen lines. The first three come first; lined is for a fourth series.
 */
export type ChartMark = "solid" | "outline" | "dotted" | "lined"

/** Series without a mark take the next one in this order. */
export const CHART_MARKS: readonly ChartMark[] = [
  "solid",
  "outline",
  "dotted",
  "lined",
]

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode
    icon?: React.ComponentType
    /** Fineliner: the series' mark; defaults by position in the config. */
    mark?: ChartMark
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>

type ChartContextProps = {
  config: ChartConfig
  /** Scopes the chart's mark patterns, so several charts on a page never share an id. */
  chartId: string
}

export const ChartContext = React.createContext<ChartContextProps | null>(null)

export function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

/** The id of a series' mark pattern (dotted, lined) inside one chart. */
export function markId(chartId: string, key: string) {
  return `${chartId}-mark-${key.replace(/[^\w-]/g, "_")}`
}

/** A series' mark, explicit or by its position in the config. Every series is drawn by the pen unless it says so. */
export function seriesMark(
  config: ChartConfig,
  key: string | undefined,
): ChartMark {
  const own = key ? config[key]?.mark : undefined
  const index = key ? Math.max(0, Object.keys(config).indexOf(key)) : 0
  return own ?? CHART_MARKS[index % CHART_MARKS.length]!
}

/** What a mark fills a shape with: the series' ink, bare paper, or its pattern. */
export function markFill(chartId: string, key: string, mark: ChartMark) {
  if (mark === "solid") return `var(--color-${key}, var(--pen))`
  if (mark === "outline") return "var(--paper)"
  return `url(#${markId(chartId, key)})`
}

/** A line's dash for a mark: dotted series draw dotted lines, lined ones dashed; the others a full line. */
export function markDash(mark: ChartMark) {
  if (mark === "dotted") return "0.1 4.5"
  if (mark === "lined") return "7 4"
  return undefined
}

/**
 * The config key an item belongs to: the value of `key` on the item or its data row (a pie slice's name, say),
 * else `key` itself. Undefined when neither is in the config.
 */
export function getPayloadConfigKey(
  config: ChartConfig,
  payload: unknown,
  key: string,
): string | undefined {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  if (configLabelKey in config) return configLabelKey
  return key in config ? key : undefined
}

"use client"

import * as React from "react"
import {
  Sector,
  type BarShapeProps,
  type CurveProps,
  type PieSectorShapeProps,
} from "recharts"
import { pen } from "@/fineliner/pen/stroke"
import { curveRuns, plot } from "@/fineliner/pen/plot"
import { snap, type Point } from "@/fineliner/pen/geometry"
import {
  getPayloadConfigKey,
  markFill,
  seriesMark,
  useChart,
} from "@/fineliner/ui/chart-context"

// Data marks drawn by the pen. Strokes pass exactly through every data point and every bar corner (pen/plot.ts):
// the wobble lives between them, so the pen draws the chart and the data stays where Recharts put it. Fills are the
// exact geometry, in the series' mark. Seeds come from the series and its values, never from layout, so server and
// browser draw the same strokes.

const ink = (key: unknown) =>
  typeof key === "string" ? `var(--color-${key}, var(--pen))` : "var(--pen)"

// Recharts re-renders shapes on hover and while animating; a small cache keeps a redraw of the same geometry free.
const cache = new Map<string, string>()
function cached(key: string, make: () => string) {
  let d = cache.get(key)
  if (d === undefined) {
    d = make()
    cache.set(key, d)
    if (cache.size > 600) cache.delete(cache.keys().next().value as string)
  }
  return d
}

// ---- Curves -------------------------------------------------------------------------------------------------------

type CurveFactory = Extract<
  NonNullable<CurveProps["type"]>,
  (...args: never[]) => unknown
>
type CurveContext = Parameters<CurveFactory>[0]

/**
 * A curve for `<Line type>` and `<Area type>` whose stroke is drawn by the pen through the exact data points. An
 * area's fill keeps the plain curve, so fill and stroke meet. Horizontal layouts.
 */
export function drawnCurve(
  interpolation: "monotone" | "linear" = "monotone",
  seed: string | number = "chart",
): CurveFactory {
  return (context: CurveContext) => {
    let inArea = false
    let closing = false
    let points: Point[] = []
    return {
      areaStart() {
        inArea = true
        closing = false
      },
      areaEnd() {
        inArea = false
      },
      lineStart() {
        points = []
      },
      point(x: number, y: number) {
        const last = points[points.length - 1]
        if (!last || last[0] !== +x || last[1] !== +y) points.push([+x, +y])
      },
      lineEnd() {
        const [start] = points
        if (!start) return
        const path = curveRuns(points, interpolation)
        const drawn = inArea
          ? [start, ...path.flatMap((r) => r.slice(1))]
          : plot(`${seed}|${points.map((p) => p.join(",")).join(";")}`).through(
              path,
            )
        if (inArea && closing) context.lineTo(...start)
        else context.moveTo(...(drawn[0] ?? start))
        for (const p of drawn.slice(1)) context.lineTo(...p)
        if (inArea && closing) context.closePath()
        if (inArea) closing = !closing
      },
    }
  }
}

// ---- Points -------------------------------------------------------------------------------------------------------

type DotProps = {
  cx?: number
  cy?: number
  dataKey?: unknown
  index?: number
  value?: unknown
}

function DrawnDot({
  cx,
  cy,
  dataKey,
  index,
  value,
  active,
}: DotProps & { active?: boolean }) {
  const { config } = useChart()
  const key = typeof dataKey === "string" ? dataKey : undefined
  const mark = seriesMark(config, key)
  if (cx == null || cy == null) return null
  const r = (active ? 4.2 : 3) * (mark === "dotted" ? 0.75 : 1)
  const p = pen(`${String(dataKey)}:${index}:${String(value)}`, "calm")
  const c: Point = [cx, cy]
  const open = mark === "outline" || mark === "lined"
  return (
    <path
      className="fl-chart-dot"
      d={open ? p.ring(c, [r, 0]) : p.disc(c, [r, 0])}
      fill={open ? "var(--paper)" : ink(key)}
      stroke={ink(key)}
      strokeWidth={active ? 1.8 : 1.3}
      strokeLinecap="round"
    />
  )
}

/** A point for `<Line dot>`: an ink disc, a drawn ring or a small dot, by the series' mark. */
export function drawnDot(props: DotProps) {
  return <DrawnDot key={`${String(props.dataKey)}-${props.index}`} {...props} />
}

/** The hovered point for `<Line activeDot>`: the same mark, larger and pressed harder. */
export function drawnActiveDot(props: DotProps) {
  return <DrawnDot {...props} active />
}

// ---- Bars and slices ----------------------------------------------------------------------------------------------

function DrawnBar(props: BarShapeProps & { dataKey?: unknown }) {
  const { x = 0, y = 0, width = 0, height = 0, dataKey, index, value } = props
  const { config, chartId } = useChart()
  const key = typeof dataKey === "string" ? dataKey : "value"
  const mark = seriesMark(config, key)
  const x0 = Math.min(x, x + width)
  const y0 = Math.min(y, y + height)
  const w = Math.abs(width)
  const h = Math.abs(height)
  const seed = `${key}:${index}:${String(value)}`
  const d = React.useMemo(
    () =>
      w < 1 || h < 1
        ? null
        : cached(`${seed}|${snap(x0)},${snap(y0)},${snap(w)},${snap(h)}`, () =>
            plot(seed).edges([
              [x0, y0],
              [x0 + w, y0],
              [x0 + w, y0 + h],
              [x0, y0 + h],
            ]),
          ),
    [x0, y0, w, h, seed],
  )
  return (
    <g className="fl-chart-bar">
      <rect
        x={x0}
        y={y0}
        width={w}
        height={h}
        fill={markFill(chartId, key, mark)}
      />
      {d && (
        <path
          d={d}
          fill="none"
          stroke={ink(key)}
          strokeWidth={1.35}
          strokeLinecap="round"
        />
      )}
    </g>
  )
}

/** A bar for `<Bar shape>`: the exact rectangle filled in the series' mark, outlined by the pen. */
export function drawnBar(props: BarShapeProps) {
  return <DrawnBar {...props} />
}

const RADIAN = Math.PI / 180
const at = (cx: number, cy: number, r: number, angle: number): Point => [
  cx + Math.cos(-RADIAN * angle) * r,
  cy + Math.sin(-RADIAN * angle) * r,
]
function arcRun(cx: number, cy: number, r: number, a0: number, a1: number) {
  const steps = Math.max(2, Math.round(snap((Math.abs(a1 - a0) * r) / 220)))
  return Array.from({ length: steps + 1 }, (_, i) =>
    at(cx, cy, r, a0 + ((a1 - a0) * i) / steps),
  )
}

function DrawnSector(props: PieSectorShapeProps) {
  const { cx = 0, cy = 0, innerRadius = 0, outerRadius = 0 } = props
  const { startAngle = 0, endAngle = 0, name, value, isActive } = props
  const { config, chartId } = useChart()
  const key = getPayloadConfigKey(config, props, "name") ?? String(name)
  const mark = seriesMark(config, key)
  const seed = `${String(name)}:${String(value)}`
  const d = React.useMemo(() => {
    const span =
      Math.sign(endAngle - startAngle) *
      Math.min(Math.abs(endAngle - startAngle), 359.9)
    const end = startAngle + span
    if (Math.abs(span) < 0.5 || outerRadius < 1) return null
    const outer = arcRun(cx, cy, outerRadius, startAngle, end)
    const inner =
      innerRadius > 0
        ? arcRun(cx, cy, innerRadius, end, startAngle)
        : [[cx, cy] as Point]
    const close = [inner[inner.length - 1]!, outer[0]!]
    return plot(seed).path([
      outer,
      [outer[outer.length - 1]!, inner[0]!],
      ...(inner.length > 1 ? [inner] : []),
      close,
    ])
  }, [cx, cy, innerRadius, outerRadius, startAngle, endAngle, seed])
  return (
    <g className="fl-chart-sector">
      <Sector {...props} fill={markFill(chartId, key, mark)} stroke="none" />
      {d && (
        <path
          d={d}
          fill="none"
          stroke={ink(key)}
          strokeWidth={isActive ? 2.2 : 1.35}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
    </g>
  )
}

/** A slice for `<Pie shape>`: the exact sector filled in its mark, outlined by the pen, pressed harder when active. */
export function drawnSector(props: PieSectorShapeProps) {
  return <DrawnSector {...props} />
}

"use client"

import { seedOf, stream } from "@/fineliner/pen/seed"
import { cn } from "@/fineliner/lib/utils"
import {
  markDash,
  markId,
  seriesMark,
  useChart,
  type ChartConfig,
  type ChartMark,
} from "@/fineliner/ui/chart-context"

// The marks that tell series apart in one pen: a stipple of pen dots and a field of pen lines, as SVG patterns defined
// once per chart. Each tile's dots sit a little off the grid and the lines lean a few degrees, by a seed from the
// series key, so the same series looks the same on the server, in the browser and in every build.

function MarkPattern({
  id,
  mark,
  color,
  seed,
}: {
  id: string
  mark: ChartMark
  color: string
  seed: string
}) {
  const r = stream(seedOf(seed), "chart-mark")
  if (mark === "lined") {
    const lean = Math.round(r.signed() * 6)
    return (
      <pattern
        id={id}
        width={5}
        height={5}
        patternUnits="userSpaceOnUse"
        patternTransform={`rotate(${45 + lean})`}
      >
        <rect width={5} height={5} fill="var(--paper)" />
        <rect width={1.1} height={5} fill={color} />
      </pattern>
    )
  }
  // A 9px tile of three dots, each nudged off its place so the stipple reads as dotted by hand.
  const dots = [
    [1.5, 1.5],
    [6, 3.5],
    [3, 7],
  ].map(([x, y]) => [x! + r.signed() * 0.6, y! + r.signed() * 0.6])
  return (
    <pattern id={id} width={9} height={9} patternUnits="userSpaceOnUse">
      <rect width={9} height={9} fill="var(--paper)" />
      {dots.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r={0.95} fill={color} />
      ))}
    </pattern>
  )
}

/** The dotted and lined series' patterns for one chart, in a hidden SVG that the chart's shapes refer to by id. */
export function ChartMarkDefs({
  chartId,
  config,
}: {
  chartId: string
  config: ChartConfig
}) {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      width="0"
      height="0"
      className="pointer-events-none absolute"
    >
      <defs>
        {Object.keys(config).map((key) => {
          const mark = seriesMark(config, key)
          return mark === "dotted" || mark === "lined" ? (
            <MarkPattern
              key={key}
              id={markId(chartId, key)}
              mark={mark}
              color={`var(--color-${key}, var(--pen))`}
              seed={key}
            />
          ) : null
        })}
      </defs>
    </svg>
  )
}

/**
 * A series' key in a tooltip or legend, in its mark: a small square filled solid, left bare, dotted or lined, or for
 * a line a short stroke in its dash with the point it marks.
 */
export function ChartSwatch({
  seriesKey,
  variant = "fill",
  className,
}: {
  seriesKey?: string
  variant?: "fill" | "line"
  className?: string
}) {
  const { chartId, config } = useChart()
  const mark = seriesMark(config, seriesKey)
  const ink = seriesKey ? `var(--color-${seriesKey}, var(--pen))` : "var(--pen)"
  const fill =
    mark === "solid"
      ? ink
      : mark === "outline" || !seriesKey
        ? "var(--paper)"
        : `url(#${markId(chartId, seriesKey)})`

  if (variant === "line") {
    return (
      <svg
        data-slot="chart-swatch"
        aria-hidden="true"
        viewBox="0 0 18 10"
        className={cn(
          "h-2.5 w-[1.125rem] shrink-0 overflow-visible",
          className,
        )}
      >
        <line
          x1={1}
          y1={5}
          x2={17}
          y2={5}
          stroke={ink}
          strokeWidth={1.5}
          strokeLinecap="round"
          strokeDasharray={markDash(mark)}
        />
        <circle
          cx={9}
          cy={5}
          r={2.4}
          fill={mark === "outline" ? "var(--paper)" : ink}
          stroke={ink}
          strokeWidth={1.2}
        />
      </svg>
    )
  }

  return (
    <svg
      data-slot="chart-swatch"
      aria-hidden="true"
      viewBox="0 0 12 12"
      className={cn("size-3 shrink-0", className)}
    >
      <rect
        x={0.75}
        y={0.75}
        width={10.5}
        height={10.5}
        rx={0.5}
        fill={fill}
        stroke={ink}
        strokeWidth={1.3}
      />
    </svg>
  )
}

"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"
import type { TooltipValueType } from "recharts"
import { cn } from "@/fineliner/lib/utils"
import { getPayloadConfigKey, useChart } from "@/fineliner/ui/chart-context"
import { ChartSwatch } from "@/fineliner/ui/chart-marks"

// The tooltip is a small sheet of paper drawn round by the pen, like a popover: the label in the label voice, one row
// per series with its mark, its name and its value in the typewriter. The legend is a row of names, each with the
// series' mark (or its stroke and point, for a line).

type TooltipNameType = number | string

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean
    hideIndicator?: boolean
    indicator?: "line" | "dot" | "dashed"
    nameKey?: string
    labelKey?: string
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart()

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null
    }

    const [item] = payload
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`
    const configKey = getPayloadConfigKey(config, item, key)
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : configKey && config[configKey]?.label

    const classes = cn("label text-pen", labelClassName)
    if (labelFormatter) {
      return <div className={classes}>{labelFormatter(value, payload)}</div>
    }

    if (!value) {
      return null
    }

    return <div className={classes}>{value}</div>
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ])

  if (!active || !payload?.length) {
    return null
  }

  return (
    <div
      data-slot="chart-tooltip"
      className={cn(
        "float-sheet frame grid min-w-36 items-start gap-hair px-tight py-hair",
        className,
      )}
    >
      {tooltipLabel}
      <div className="grid gap-1">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`
            const configKey = getPayloadConfigKey(config, item, key)
            const itemConfig = configKey ? config[configKey] : undefined

            return (
              <div
                key={index}
                className="flex w-full items-center gap-tight [&>svg:not([data-slot=chart-swatch])]:size-3 [&>svg:not([data-slot=chart-swatch])]:text-pen-quiet"
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <ChartSwatch
                          seriesKey={configKey}
                          variant={indicator === "dot" ? "fill" : "line"}
                        />
                      )
                    )}
                    <div className="flex flex-1 items-baseline justify-between gap-snug">
                      <span className="text-small leading-small text-pen-quiet">
                        {itemConfig?.label ?? item.name}
                      </span>
                      {item.value != null && (
                        <span className="font-type text-small leading-none text-pen tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString("en-GB")
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
      </div>
    </div>
  )
}

function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: React.ComponentProps<"div"> & {
  hideIcon?: boolean
  nameKey?: string
} & RechartsPrimitive.DefaultLegendContentProps) {
  const { config } = useChart()

  if (!payload?.length) {
    return null
  }

  const keys = Object.keys(config)
  const order = (key?: string) => {
    const at = key ? keys.indexOf(key) : -1
    return at < 0 ? keys.length : at
  }

  return (
    <div
      data-slot="chart-legend"
      className={cn(
        "flex flex-wrap items-center justify-center gap-x-snug gap-y-hair",
        verticalAlign === "top" ? "pb-tight" : "pt-tight",
        className,
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`
          return { item, configKey: getPayloadConfigKey(config, item, key) }
        })
        // In config order, the order marks are dealt in, not Recharts' alphabetical one.
        .sort((a, b) => order(a.configKey) - order(b.configKey))
        .map(({ item, configKey }, index) => {
          const itemConfig = configKey ? config[configKey] : undefined
          return (
            <div
              key={index}
              className="flex items-center gap-1.5 text-small leading-small text-pen-quiet [&>svg:not([data-slot=chart-swatch])]:size-3"
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <ChartSwatch
                  seriesKey={configKey}
                  variant={item.type === "line" ? "line" : "fill"}
                />
              )}
              {itemConfig?.label ?? item.value}
            </div>
          )
        })}
    </div>
  )
}

export { ChartTooltipContent, ChartLegendContent }

"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"
import { cn } from "@/fineliner/lib/utils"
import {
  ChartContext,
  THEMES,
  markFill,
  seriesMark,
  type ChartConfig,
} from "@/fineliner/ui/chart-context"
import { ChartMarkDefs } from "@/fineliner/ui/chart-marks"

// A chart drawn with the page's one pen: every series in the pen, told apart by its mark (solid, outline, dotted,
// lined); bars, lines, points and slices drawn by the pen through the exact data (drawnBar, drawnCurve, drawnDot,
// drawnSector in chart-drawn.tsx). Axis figures in the typewriter, grid lines faint dotted pencil. The data never
// moves and never boils.

const INITIAL_DIMENSION = { width: 320, height: 200 } as const

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"]
  initialDimension?: {
    width: number
    height: number
  }
}) {
  const uniqueId = React.useId()
  const chartId = `chart-${(id ?? uniqueId).replace(/[^\w-]/g, "")}`
  const context = React.useMemo(() => ({ config, chartId }), [config, chartId])

  return (
    <ChartContext.Provider value={context}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "relative flex aspect-video justify-center font-type text-small text-pen-quiet",
          // Axes: typewriter figures in the quiet pen; the axis line in the pen; grid lines faint dotted pencil.
          "[&_.recharts-cartesian-axis-tick-value]:fill-pen-quiet [&_.recharts-cartesian-axis-tick-value]:tabular-nums [&_.recharts-polar-angle-axis-tick_text]:fill-pen-quiet [&_.recharts-label]:fill-pen-quiet",
          "[&_.recharts-cartesian-axis-line[stroke='#666']]:stroke-pen [&_.recharts-cartesian-axis-tick-line[stroke='#666']]:stroke-pen-quiet [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-pen-faint [&_.recharts-cartesian-grid_line[stroke='#ccc']:not([stroke-dasharray])]:[stroke-dasharray:0.1_5] [&_.recharts-cartesian-grid_line]:[stroke-linecap:round] [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-pen-faint [&_.recharts-reference-line_[stroke='#ccc']]:stroke-pen",
          // Hover: a dashed pencil line, or a band of tint behind the bars.
          "[&_.recharts-curve.recharts-tooltip-cursor]:stroke-pen-faint [&_.recharts-curve.recharts-tooltip-cursor]:[stroke-dasharray:3_3] [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-tint [&_.recharts-radial-bar-background-sector]:fill-tint [&_.recharts-dot[stroke='#fff']]:stroke-paper [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-sector]:outline-hidden [&_.recharts-surface]:overflow-visible",
          className,
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <ChartMarkDefs chartId={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
}

// Writes --mark-<key> for every series (its fill: ink, bare paper or its pattern, as `fill="var(--mark-<key>)"`) and
// --color-<key> for a series that names a colour. A series without one draws in the page's pen, which is the point:
// one pen, told apart by marks.
const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const keys = Object.keys(config)

  const blocks = Object.entries(THEMES).map(([theme, prefix]) => {
    const night = theme !== "light"
    const lines = keys.flatMap((key) => {
      const item = config[key]
      const color =
        item?.theme?.[theme as keyof typeof item.theme] ?? item?.color
      return [
        color ? `  --color-${key}: ${color};` : null,
        night
          ? null
          : `  --mark-${key}: ${markFill(id, key, seriesMark(config, key))};`,
      ].filter((line) => line !== null)
    })
    return lines.length
      ? `${prefix} [data-chart="${id}"] {\n${lines.join("\n")}\n}`
      : ""
  })
  const css = blocks.join("\n").trim()

  return css ? <style dangerouslySetInnerHTML={{ __html: css }} /> : null
}

